import{$ as e,A as t,B as n,V as r}from"./chunks/framework.Civ1omIV.js";var i=JSON.parse(`{"title":"Clash 与 Surge 兼容吗？","description":"说明如何把 Surge Profile 中的订阅、Snell、Shadowsocks、Trojan、WireGuard 等节点与分流策略迁移到 Clash iOS。","frontmatter":{"title":"Clash 与 Surge 兼容吗？","description":"说明如何把 Surge Profile 中的订阅、Snell、Shadowsocks、Trojan、WireGuard 等节点与分流策略迁移到 Clash iOS。","head":[["meta",{"name":"keywords","content":"Surge转Clash,Surge iOS,Surge Profile,Snell iOS,Surge订阅,Clash iOS"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"FAQPage\\",\\"mainEntity\\":[{\\"@type\\":\\"Question\\",\\"name\\":\\"如何把 Surge Profile 迁移到 Clash？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"把节点与分流策略整理为 mihomo YAML，或添加服务商提供的 Clash / mihomo 订阅；模块、脚本和重写可使用 Clash 中对应的规则与功能重新建立。\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Clash 支持 Surge 的 Snell 节点吗？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"支持。可以通过 mihomo YAML、兼容订阅或节点编辑器添加 Snell 节点。\\"}}]}"]]},"headers":[],"relativePath":"zh/guide/compatibility/surge.md","filePath":"zh/guide/compatibility/surge.md","lastUpdated":0}`),a={name:`zh/guide/compatibility/surge.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="clash-与-surge-兼容吗" tabindex="-1">Clash 与 Surge 兼容吗？ <a class="header-anchor" href="#clash-与-surge-兼容吗" aria-label="Permalink to “Clash 与 Surge 兼容吗？”">​</a></h1><p><strong>共同的节点协议可以继续使用，分流策略可以整理为 mihomo YAML。</strong></p><p><a href="https://manual.nssurge.com/overview/quick-start.html" target="_blank" rel="noreferrer">Surge 使用自己的 Profile 格式</a>，包含 <code>[General]</code>、<code>[Proxy]</code>、<code>[Proxy Group]</code>、<code>[Rule]</code> 等段落。迁移时可把节点与策略组整理为 mihomo YAML，并使用 Clash 的规则与对应功能重新建立原有分流体验。</p><h2 id="哪些-surge-节点可以继续使用" tabindex="-1">哪些 Surge 节点可以继续使用？ <a class="header-anchor" href="#哪些-surge-节点可以继续使用" aria-label="Permalink to “哪些 Surge 节点可以继续使用？”">​</a></h2><p>Clash 支持 Snell，也支持双方共有的多种出站协议，例如：</p><ul><li>HTTP 与 SOCKS；</li><li>Shadowsocks；</li><li>VMess 与 Trojan；</li><li>WireGuard；</li><li>Snell。</li></ul><p>Snell 通常通过 mihomo YAML、返回 mihomo YAML 的兼容订阅或节点编辑器添加。其他节点也可以根据服务器与协议参数在节点编辑器中重新添加。</p><h2 id="怎么迁移" tabindex="-1">怎么迁移？ <a class="header-anchor" href="#怎么迁移" aria-label="Permalink to “怎么迁移？”">​</a></h2><ol><li>优先获取服务商提供的 mihomo / Clash 订阅。</li><li>如果只有 Surge Profile，提取需要的节点参数，在 Clash 中重新添加。</li><li>将 Surge 的策略组和规则改写为 mihomo YAML。</li><li>使用 Clash 的规则与对应功能重新建立模块、脚本、重写所表达的需求。</li></ol><h2 id="迁移时需要重新配置的内容" tabindex="-1">迁移时需要重新配置的内容 <a class="header-anchor" href="#迁移时需要重新配置的内容" aria-label="Permalink to “迁移时需要重新配置的内容”">​</a></h2><ul><li>将 Surge Profile 的节点与策略整理为 mihomo YAML；</li><li>使用 Clash 规则表达原有分流逻辑；</li><li>使用对应功能重新建立 Module、Rewrite、MITM 与脚本需求；</li><li>按自己的使用习惯设置 App 偏好。</li></ul><p>协议和参数对应后，同一台服务器可以直接使用。</p><p>返回<a href="/clash.md/zh/guide/compatibility">兼容性总览</a>。</p>`,13)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};